}

typedef long long ll;
ll gcd(ll a, ll b) { return b ? gcd(b, a % b) : a; }
ll f(ll x, ll c, ll n) { return ((__int128)x * x + c) % n; }
ll pollard(ll n) {
  ll x = rand() % n, y = x, c = rand() % n, d = 1;
  for (int k = 1;; k <<= 1, y = x) {
    for (int i = 1; i <= k; i++) {
      x = f(x, c, n);
      d = gcd(abs(x - y), n);
      if (d > 1 && d < n) return d;
    }
    if (d == n) break;
  }
  return n;
}

int phi[MAXN], prime[MAXN], cnt, vis[MAXN];
void getphi(int n) {
  phi[1] = 1;
  for (int i = 2; i <= n; i++) {
    if (!vis[i]) {
      prime[cnt++] = i;
      phi[i] = i - 1;
    }
    for (int j = 0; j < cnt && i * prime[j] <= n; j++) {
      vis[i * prime[j]] = 1;
      if (i % prime[j] == 0) {
        phi[i * prime[j]] = phi[i] * prime[j];
        break;
      } else {
        phi[i * prime[j]] = phi[i] * (prime[j] - 1);
      }
    }
  }
}

int mu[MAXN], prime[MAXN], cnt, vis[MAXN];
void getmu(int n) {
  mu[1] = 1;
  for (int i = 2; i <= n; i++) {
    if (!vis[i]) {
      prime[cnt++] = i;
      mu[i] = -1;
    }
    for (int j = 0; j < cnt && i * prime[j] <= n; j++) {
      vis[i * prime[j]] = 1;
      if (i % prime[j] == 0) {
        mu[i * prime[j]] = 0;
        break;
      } else {
        mu[i * prime[j]] = -mu[i];
      }
    }
  }
}

int minp[MAXN], prime[MAXN], cnt, vis[MAXN];
void getminp(int n) {
  for (int i = 2; i <= n; i++) {
    if (!vis[i]) {
      prime[cnt++] = i;
      minp[i] = i;
    }
    for (int j = 0; j < cnt && i * prime[j] <= n; j++) {
      vis[i * prime[j]] = 1;
      minp[i * prime[j]] = prime[j];
      if (i % prime[j] == 0) break;
    }
  }
}

int prime[MAXN], cnt, vis[MAXN], sum[MAXN];
void getpi(int n) {
  for (int i = 2; i <= n; i++) {
    if (!vis[i]) prime[cnt++] = i;
    for (int j = 0; j < cnt && i * prime[j] <= n; j++) {
      vis[i * prime[j]] = 1;
      if (i % prime[j] == 0) break;
    }
    sum[i] = cnt;
  }
}

bool vis[MAXN];
void seg_sieve(long long L, long long R) {
  long long m = sqrt(R) + 1;
  fill(vis, vis + (R - L + 1), 0);
  for (long long i = 2; i <= m; i++)
    for (long long j = max(i * i, (L + i - 1) / i * i); j <= R; j += i)
      vis[j - L] = 1;
  if (L == 1) vis[0] = 1;
}

typedef long long ll;
ll fac[64];
int cnt;
void factor(ll n) {
  cnt = 0;
  for (ll i = 2; i * i <= n; i++) {
    if (n % i == 0) {
      fac[cnt++] = i;
      while (n % i == 0) n /= i;
    }
  }
  if (n > 1) fac[cnt++] = n;
}

long long qpow(long long a, long long k, long long p) {
  long long res = 1;
  a %= p;
  while (k) {
    if (k & 1) res = res * a % p;
    a = a * a % p;
    k >>= 1;
  }
  return res;
}

long long exgcd(long long a, long long b, long long &x, long long &y) {
  if (!b) {
    x = 1;
    y = 0;
    return a;
  }
  long long d = exgcd(b, a % b, y, x);
  y -= a / b * x;
  return d;
}

long long inv(long long a, long long p) {
  return qpow(a, p - 2, p);
}

long long inv(long long a, long long p) {
  long long x, y;
  exgcd(a, p, x, y);
  return (x % p + p) % p;
}
